record.field:
readings = env['x_meter_reading'].search_fetch([('id', 'in', record.x_property.x_meter_reading_ids.ids), ('x_meter_id', '=', record.x_meter_id.id)], ['x_quantity'], order='x_date')
for i in range(len(readings)):
    readings[i]['x_usage'] = readings[i].x_quantity - readings[i-1].x_quantity if i else 0

for line in record:
    if line.x_end_date and line.x_end_date < line.x_start_date: raise UserError("End Date must be empty or after Start Date.")
    domain = [('id', '!=', line.id), ('x_property_id', '=', line.x_property_id.id), ('x_type', '=', line.x_type), ('x_start_date', '!=', False), '|', ('x_end_date', '=', False), ('x_end_date', '>=', line.x_start_date)]
    if line.x_end_date: domain.append(('x_start_date', '<=', line.x_end_date))
    if env['x_stake_holder'].search_count(domain, limit=1): raise UserError("Stakeholder dates cannot overlap for the same property. Ensure that periods do not overlap.")

dist_key = record.x_distribution_key
if not dist_key:
    record.invoice_line_ids.write({'analytic_distribution': {}})
else:
    analytic_distribution = {}
    period_start, period_end = record.x_period_start, record.x_period_end
    periods_valid = bool(period_start) and bool(period_end)

    if dist_key.x_based_on == "Shares" and periods_valid:
        for ratio in dist_key.x_ratio_ids.filtered('x_ratio'):
            for account in ratio.x_property_ratios.x_account_ids:
                acc_start, acc_end = account.x_start_date, account.x_end_date
                if acc_start <= period_end and (not acc_end or period_start <= acc_end):
                    overlap_start, overlap_end = max(acc_start, period_start), acc_end if acc_end else period_end
                    analytic_distribution[account.id] = analytic_distribution.get(account.id, 0) + ((overlap_end - overlap_start).days + 1) * ratio.x_ratio

    elif dist_key.x_based_on == "Meter Readings" and periods_valid:
        splitter = env.ref('property_assets_distribution.action_meter_splitter')
        for property in env['x_property'].search([('x_company_id', '=', dist_key.x_company_id.id)]):
            meter_id = dist_key.x_meter.id
            readings = env['x_meter_reading'].browse([mr.id for mr in property.x_meter_reading_ids if mr.x_meter_id.id == meter_id])
            if len(readings) < 2: continue
            shares = {}
            splitter.with_context(accounts=property.x_account_ids, readings=readings, period_start=period_start, period_end=period_end, result=shares).run()
            analytic_distribution.update({p.id: qty for p, qty in shares.items() if not isinstance(p, str)})

    # Outcome
    if (total_ratio := sum(analytic_distribution.values())):
        for key in analytic_distribution: analytic_distribution[key] *= 100 / total_ratio
        record.invoice_line_ids.write({'analytic_distribution': analytic_distribution})
    else:
        record.invoice_line_ids.write({'analytic_distribution': {}})

for record in records:
    for line in record.invoice_line_ids:
        order = line.sale_line_ids.order_id
        if order and order.is_subscription and order.x_property_id:
            analytic_account = env['account.analytic.account'].search([('partner_id', '=', record.partner_id.id), ('x_property', '=', order.x_property_id.id)], limit=1)
            line['analytic_distribution'] = {analytic_account.id: 100}
